import java.util.*;

class Solution {
    public String makeGood(String s) {
        StringBuilder sb = new StringBuilder();          // stack of survivors
        for (char c : s.toCharArray()) {
            int last = sb.length() - 1;
            if (last >= 0 && Math.abs(sb.charAt(last) - c) == 32) sb.deleteCharAt(last); // e.g. 'q' and 'Q'
            else sb.append(c);
        }
        return sb.toString();
    }
}

