function makeGood(s) {
  let st = "";
  for (const c of s) { const t = st[st.length - 1]; if (t !== undefined && Math.abs(t.charCodeAt(0) - c.charCodeAt(0)) === 32) st = st.slice(0, -1); else st += c; }
  return st;
}
